// ─────────────────────────────────────────────────────────────────────────────
// Parse & Verify Webhook Events
// Accepts HubSpot app webhook batches:
//   conversation.newMessage                → threadId (+ messageId)
//   ticket.creation / ticket.propertyChange → ticketId
// and a simple custom body ({ "ticketId": "…" } or { "ticketIds": [...] }) from
// a HubSpot workflow webhook action. Verifies the HubSpot v3 signature outside
// sandbox, ignores this integration's own property writes (loop guard) and
// de-duplicates.
// Security note: HUBSPOT_APP_CLIENT_SECRET is read here only because an HMAC
// cannot be computed in an HTTP header field. It never leaves this node.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const req = $('Ticket Reply Webhook').first().json;
const headers = Object.fromEntries(Object.entries(req.headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
let signature = 'skipped (sandbox)';
if (!cfg.sandboxMode && cfg.requireSignature) {
  const sig = headers['x-hubspot-signature-v3']; const ts = headers['x-hubspot-request-timestamp'];
  if (!sig || !ts) throw new Error('Rejected: missing HubSpot v3 signature headers.');
  if (!Number.isFinite(Number(ts)) || Math.abs(Date.now() - Number(ts)) > 300000) throw new Error('Rejected: HubSpot request timestamp outside the 5-minute window.');
  let secret = ''; try { secret = String($env.HUBSPOT_APP_CLIENT_SECRET || ''); } catch (e) { secret = ''; }
  if (!secret) throw new Error('Rejected: HUBSPOT_APP_CLIENT_SECRET is not set and REQUIRE_HUBSPOT_SIGNATURE is not false.');
  let crypto; try { crypto = require('crypto'); } catch (e) { throw new Error('Signature verification needs NODE_FUNCTION_ALLOW_BUILTIN=crypto.'); }
  const raw = typeof req.body === 'string' ? req.body : JSON.stringify(req.body);
  const expected = crypto.createHmac('sha256', secret).update(`POST${cfg.webhookPublicUrl || req.webhookUrl}${raw}${ts}`, 'utf8').digest('base64');
  const a = Buffer.from(String(sig)); const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Rejected: HubSpot v3 signature mismatch.');
  signature = 'verified';
} else if (!cfg.sandboxMode) signature = 'disabled (REQUIRE_HUBSPOT_SIGNATURE=false)';

let body = req.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const events = Array.isArray(body) ? body : [body];
const OWN = new Set([cfg.flagProperty, cfg.scoreProperty, cfg.lastAlertProperty, cfg.lastAlertTierProperty, 'hs_ticket_priority'].filter(Boolean));
const items = []; const ignored = [];
const seen = new Set();
const push = (it) => { const k = it.threadId ? `th:${it.threadId}` : `tk:${it.ticketId}`; if (!seen.has(k)) { seen.add(k); items.push(it); } };
for (const e of events) {
  if (!e || typeof e !== 'object') continue;
  if (e.subscriptionType) {
    if (cfg.hubspotAppId && String(e.sourceId || '') === cfg.hubspotAppId) { ignored.push({ reason: 'own_write', objectId: e.objectId }); continue; }
    if (e.subscriptionType === 'conversation.newMessage') push({ threadId: String(e.objectId), messageId: e.messageId ? String(e.messageId) : null, ticketId: null });
    else if (/^ticket\./.test(e.subscriptionType)) {
      if (e.propertyName && OWN.has(e.propertyName)) { ignored.push({ reason: 'own_property', objectId: e.objectId }); continue; }
      push({ ticketId: String(e.objectId), threadId: null, messageId: null });
    } else ignored.push({ reason: `unsupported_${e.subscriptionType}`, objectId: e.objectId });
  } else {
    for (const id of [e.ticketId, e.ticket_id, e.objectId, ...(Array.isArray(e.ticketIds) ? e.ticketIds : [])].filter(Boolean)) if (/^\d+$/.test(String(id))) push({ ticketId: String(id), threadId: null, messageId: null });
  }
}
return [{ json: { signature, received: events.length, items: items.slice(0, cfg.maxTicketsPerRun), ignored } }];

