  const r = resp[i].json || {};
  if (r.error) { dropped.push({ ticketId: w.json.ticketId, threadId: w.json.threadId, reason: 'thread_lookup_failed' }); return; }
  const threads = Array.isArray(r.results) ? r.results : (r.id ? [r] : []);
  const th = threads.sort((a, b) => String(b.latestMessageTimestamp || b.createdAt || '').localeCompare(String(a.latestMessageTimestamp || a.createdAt || '')))[0];
  const threadId = w.json.threadId || (th ? String(th.id) : null);
  const ticketId = w.json.ticketId || th?.threadAssociations?.associatedTicketId || null;
  if (!threadId || !ticketId) { dropped.push({ ticketId: w.json.ticketId, threadId: w.json.threadId, reason: !threadId ? 'no_conversation_thread' : 'thread_without_ticket' }); return; }
