// ── Trigger dictionary (category → weight, optional tier floor, phrases) ──
const CATEGORIES = {
  legal: { weight: 45, floor: 'critical', phrases: ['lawyer', 'lawyers', 'attorney', 'legal action', 're:(?:involve|involving|contact|contacting|forward(?:ing)?(?: this)? to|hand(?:ing)?(?: this)?(?: over)? to|escalat\\w*(?: this)? to|refer(?:ring)?(?: this)? to) (?:our )?legal\\b', 'sue you', 'lawsuit', 'take legal', 'small claims', 'chargeback', 'report you to', 'regulator', 'ombudsman', 'breach of contract'] },
  // "cancel" counts only with an account/contract object or as stated intent,
