  churn: { weight: 35, floor: 'high', phrases: ['re:cancel(?:l?ing|led|lation)?\\b(?=[^.!?]{0,40}\\b(?:subscription|account|contract|plan|service|licen[cs]e|renewal|membership|with you)\\b)', "re:\\b(?:we|i)(?:'ll| will| are going to|'re going to| am going to|'m going to| want to| plan to| intend to| are about to|'re about to)\\s+(?:cancel|leave|churn)\\b", 'terminate the contract', 'terminate our contract', 'not renewing', "won't renew", 'will not renew', 'switching to', 'switch to another', 'moving to a competitor', 'another vendor', 'another provider', 'end our subscription', 'close our account'] },
  refund: { weight: 18, phrases: ['refund', 'money back', 'credit for the downtime', 'compensation'] },
  escalation: { weight: 22, phrases: ['escalate', 'escalated', 'escalation', 'manager', 'supervisor', 'someone senior', 'your ceo', 'your boss', 'head of support', 'executive'] },
  frustration: { weight: 20, phrases: ['unacceptable', 'ridiculous', 'terrible support', 'terrible service', 'awful', 'worst', 'useless', 'fed up', 'furious', 'disappointed', 'frustrated', 'frustrating', 'angry', 'appalling', 'disgraceful', 'joke', 'waste of time', 'not good enough'] },
  repetition: { weight: 16, phrases: ['still waiting', 'still not', 'broken again', 'down again', 'failed again', 'third time', 'fourth time', 'again and again', 'how many times', 'keep asking', 'nobody has responded', 'no one has responded', 'no response', 'no reply', 'for the last time', 'yet again', 'supposed to be fixed'] },
  urgency: { weight: 12, phrases: ['urgent', 'urgently', 'asap', 'immediately', 'right now', 'production down', 'outage', 'business critical', 'losing money', 'losing customers', 'whole team is blocked'] },
};
for (const [k, w] of Object.entries(cfg.keywordWeights || {})) if (CATEGORIES[k] && Number.isFinite(Number(w))) CATEGORIES[k].weight = Math.max(0, Math.min(100, Number(w)));
for (const extra of cfg.extraKeywords || []) { const [phrase, cat] = extra.split(':').map((x) => x.trim().toLowerCase()); if (phrase && CATEGORIES[cat]) CATEGORIES[cat].phrases.push(phrase); }
const POSITIVE = ['thank you', 'thanks', 'appreciate', 'resolved', 'fixed it', 'works now', 'working now', 'great job', 'perfect', 'all good', 'brilliant', 'awesome'];
const COMPLAINT_NEG = /\b(isn't|is not|not|doesn't|does not|don't|haven't|hasn't|wasn't|aren't|still not)\s+(been\s+)?(fixed|working|resolved|sorted|done|answered|responded|back|improved|heard|addressed)\b/;
const NEGATORS = /\b(no|not|never|don't|dont|do not|won't|wont|isn't|aren't|without|no need to|nothing to)\b/;
const AUTO_SUBJECT = /\b(automatic reply|auto[- ]?reply|autoreply|out of (the )?office|ooo|undeliverable|delivery status notification|mail delivery (failed|subsystem)|returned mail|delivery failure)\b/i;
const AUTO_BODY = /\b(i am|i'm) (currently )?(out of (the )?office|away from (the )?office|on (annual |parental )?leave|on vacation|travell?ing with limited)|automatic reply|this is an auto(mated|matic)[- ]?(reply|response|message)|delivery status notification|could not be delivered|mail delivery failed|mailbox (is )?full|recipient address rejected/i;
const AUTO_SENDER = /^(mailer-daemon|postmaster|no-?reply|do-?not-?reply|bounce[s]?|notifications?)@/i;
const RANK = { low: 0, moderate: 1, high: 2, critical: 3 };

const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const senderEmail = (m) => String(m.senders?.[0]?.deliveryIdentifier?.value || m.senders?.[0]?.email || '').toLowerCase();
