function classify(m) {
  if (String(m.type || 'MESSAGE').toUpperCase() !== 'MESSAGE') return 'internal_note';
  if (String(m.direction || '').toUpperCase() !== 'INCOMING') return 'agent_reply';
  const email = senderEmail(m);
  if (AUTO_SENDER.test(email)) return 'bounce_or_system';
  if (AUTO_SUBJECT.test(String(m.subject || '')) || AUTO_BODY.test(String(m.text || ''))) return 'auto_reply';
  if (email && isInternal(email)) return 'internal_sender';
