        if (!cats[cat]) { cats[cat] = 0; score += def.weight; }
        cats[cat] += 1;
        if (cats[cat] > 1 && cats[cat] <= 3) score += 3; // extra distinct hits in a category
        matched.push({ category: cat, phrase: label, negated: false });
        break;
      }
    }
  }
  // Typography
  const excl = (raw.match(/!/g) || []).length;
  const runs = (raw.match(/[!?]{2,}/g) || []).length;
  const typo = Math.min(14, Math.max(0, excl - 1) * 2 + runs * 2);
  if (typo) { score += typo; matched.push({ category: 'urgency_typography', phrase: `${excl}× "!"${runs ? `, ${runs} run(s)` : ''}`, negated: false }); }
  const letters = raw.replace(/[^A-Za-z]/g, '');
  const words = raw.split(/\s+/).filter((w) => /[A-Za-z]{3,}/.test(w));
  const capsWords = words.filter((w) => { const l = w.replace(/[^A-Za-z]/g, ''); return l.length >= 3 && l === l.toUpperCase(); });
  const capsRatio = words.length ? capsWords.length / words.length : 0;
  if (letters.length >= 20 && capsRatio >= 0.5) { score += 16; matched.push({ category: 'urgency_typography', phrase: `ALL-CAPS ${Math.round(capsRatio * 100)}%`, negated: false }); }
  else if (letters.length >= 20 && capsRatio >= 0.25) { score += 6; matched.push({ category: 'urgency_typography', phrase: `caps ${Math.round(capsRatio * 100)}%`, negated: false }); }
  // Consecutive unanswered customer messages
  if (followUps >= 2) { const add = Math.min(18, (followUps - 1) * 7); score += add; matched.push({ category: 'repeated_follow_up', phrase: `${followUps} customer messages without an agent reply`, negated: false }); }
  // Positive dampener (never offsets legal/churn signals)
  const positive = POSITIVE.filter((p) => new RegExp(`(^|[^a-z])${esc(p)}([^a-z]|$)`).test(t));
  if (positive.length && !cats.legal && !cats.churn) { score -= 15 + 5 * Math.min(2, positive.length - 1); matched.push({ category: 'positive', phrase: positive.slice(0, 3).join(', '), negated: false }); }
  return { score: Math.max(0, Math.min(100, Math.round(score))), matched, categories: cats, capsRatio: Math.round(capsRatio * 100) / 100, exclamations: excl };
}

function tierOf(s, cats) {
  if (cats.legal || s >= cfg.criticalThreshold) return 'critical';
  if (cats.churn || s >= cfg.highThreshold) return 'high';
  if (s >= cfg.moderateThreshold) return 'moderate';
  return 'low';
}
const redact = (s) => String(s || '')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
  .replace(/\+?\(?\d[\d\s().-]{6,}\d/g, (m) => (m.replace(/\D/g, '').length >= 7 ? '[phone]' : m))
  .replace(/\b\d{5,}\b/g, '[number]')
  .replace(/\s+/g, ' ').trim();

const results = [];
for (const tk of tickets) {
  const msgs = [...(tk.messages || [])].sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
  const classified = msgs.map((m) => ({ m, cls: classify(m) }));
  const ignored = classified.filter((x) => x.cls !== 'customer' && x.cls !== 'agent_reply').map((x) => ({ messageId: x.m.id, reason: x.cls }));
  const customer = classified.filter((x) => x.cls === 'customer');
  let target = tk.eventMessageId ? customer.find((x) => x.m.id === tk.eventMessageId) : customer[customer.length - 1];
  const base = { ticketId: tk.ticketId, threadId: tk.threadId, company: tk.company, contact: tk.contact, ticket: tk.ticket, ignoredMessages: ignored };
  if (!target) { results.push({ ...base, scored: false, skipReason: ignored.length ? `no_genuine_customer_message (${[...new Set(ignored.map((i) => i.reason))].join(', ')})` : 'no_customer_message', should_escalate: false }); continue; }
  if (since && Date.parse(target.m.createdAt) < since && !tk.eventMessageId) { results.push({ ...base, scored: false, skipReason: 'no_new_customer_message_in_window', should_escalate: false }); continue; }
  // Consecutive customer messages ending at the target, with no agent reply in between.
  let followUps = 0;
  for (let i = classified.indexOf(target); i >= 0; i -= 1) {
    if (classified[i].cls === 'agent_reply') break;
    if (classified[i].cls === 'customer') followUps += 1;
  }
  const s = scoreText(target.m.text, followUps);
  // Baseline: stored score, else earlier customer messages (up to 3).
  const stored = Number(tk.ticket?.properties?.[cfg.scoreProperty]);
  const prior = customer.filter((x) => x !== target && Date.parse(x.m.createdAt) < Date.parse(target.m.createdAt)).slice(-3).map((x) => scoreText(x.m.text, 0).score);
  const baseline = Number.isFinite(stored) && tk.ticket?.properties?.[cfg.scoreProperty] !== null && tk.ticket?.properties?.[cfg.scoreProperty] !== '' ? stored : prior.length ? Math.round(prior.reduce((a, b) => a + b, 0) / prior.length) : null;
  const delta = baseline === null ? null : s.score - baseline;
  const isRegression = delta !== null && delta >= cfg.regressionDelta && s.score >= cfg.regressionMinScore;
  const tier = tierOf(s.score, s.categories);
  const shouldEscalate = RANK[tier] >= RANK[cfg.escalateMinTier] || (isRegression && RANK[tier] >= RANK.moderate);
  results.push({
    ...base, scored: true,
    messageId: target.m.id, messageAt: target.m.createdAt,
    frustration_score: s.score, severity_tier: tier,
    matched_triggers: s.matched.filter((x) => !x.negated).map((x) => `${x.category}: ${x.phrase}`),
    negated_triggers: s.matched.filter((x) => x.negated).map((x) => `${x.category}: ${x.phrase}`),
    sentiment_baseline: baseline, baseline_source: Number.isFinite(stored) && baseline === stored ? 'ticket_property' : prior.length ? 'thread_history' : 'none',
    sentiment_delta: delta, is_regression: isRegression, consecutive_follow_ups: followUps,
    caps_ratio: s.capsRatio, exclamations: s.exclamations,
    should_escalate: shouldEscalate,
    preview: (() => { const r = redact(target.m.text); return r.length > cfg.previewChars ? `${r.slice(0, cfg.previewChars - 1)}…` : r; })(),
  });
}
const counts = { tickets: results.length, scored: results.filter((r) => r.scored).length, skipped: results.filter((r) => !r.scored).length, critical: 0, high: 0, moderate: 0, low: 0, regressions: results.filter((r) => r.is_regression).length, should_escalate: results.filter((r) => r.should_escalate).length };
for (const r of results) if (r.scored) counts[r.severity_tier] += 1;
return [{ json: { source, sinceIso: sinceIso || null, counts, results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Cooldown & Escalation Gate
// Suppresses a repeat alert for the same ticket within COOLDOWN_HOURS, using
// both the ticket property LAST_ALERT_PROPERTY (shared across n8n instances,
// when written back) and workflow static data (production executions).
// A higher severity tier than the last alert breaks through the cooldown.
// Caps alerts per run at MAX_ALERTS_PER_RUN, highest score first.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const sc = $input.first().json;
const RANK = { low: 0, moderate: 1, high: 2, critical: 3 };
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const mem = (store && store.alerts) || {};
const now = Date.now();
const escalations = []; const suppressed = [];
for (const r of sc.results.filter((x) => x.should_escalate).sort((a, b) => b.frustration_score - a.frustration_score)) {
  const propAt = Date.parse(r.ticket?.properties?.[cfg.lastAlertProperty] || '');
  const propTier = String(r.ticket?.properties?.[cfg.lastAlertTierProperty] || '').toLowerCase();
  const m = mem[r.ticketId];
  const candidates = [Number.isFinite(propAt) ? { at: propAt, tier: propTier || 'high', via: 'ticket_property' } : null, m ? { at: m.at, tier: m.tier, via: 'workflow_memory' } : null].filter(Boolean);
  const last = candidates.sort((a, b) => b.at - a.at)[0];
  if (last && now - last.at < cfg.cooldownHours * 3600000) {
    if (RANK[r.severity_tier] > (RANK[last.tier] ?? 2)) { escalations.push({ ...r, cooldownBypass: `tier rose from ${last.tier} to ${r.severity_tier}` }); continue; }
    suppressed.push({ ticketId: r.ticketId, tier: r.severity_tier, score: r.frustration_score, reason: `cooldown (${last.via}, alerted ${Math.round((now - last.at) / 60000)} min ago as ${last.tier})` });
    continue;
  }
  escalations.push({ ...r, cooldownBypass: null });
}
const capped = escalations.slice(cfg.maxAlertsPerRun).map((r) => ({ ticketId: r.ticketId, tier: r.severity_tier, score: r.frustration_score, reason: 'over_max_alerts_per_run' }));
return [{ json: { ...sc, escalations: escalations.slice(0, cfg.maxAlertsPerRun), suppressed: [...suppressed, ...capped] } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Slack Escalation Alerts
// One Block Kit message per escalation: tier, ticket, account and tier, score,
// regression, matched triggers, redacted preview and a HubSpot link built from
// HUBSPOT_TICKET_URL_TEMPLATE. Contact names appear only with
// SHOW_CONTACT_NAME=true; emails and phone numbers never appear.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const g = $input.first().json;
const ICON = { critical: '🔴', high: '🟠', moderate: '🟡', low: '⚪' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = (id) => (cfg.portalId && cfg.ticketUrlTemplate ? cfg.ticketUrlTemplate.replace('{portalId}', cfg.portalId).replace('{ticketId}', id) : null);
const alerts = g.escalations.map((r) => {
  const p = r.ticket?.properties || {};
  const url = link(r.ticketId);
  const delta = r.sentiment_delta === null ? 'n/a (no baseline)' : `${r.sentiment_delta > 0 ? '+' : ''}${r.sentiment_delta} vs ${r.sentiment_baseline} (${r.baseline_source.replace('_', ' ')})`;
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `${ICON[r.severity_tier]} ${r.severity_tier.toUpperCase()} customer frustration · Ticket ${r.ticketId}`.slice(0, 150), emoji: true } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Account*\n${esc(r.company?.name || 'Unknown company')}` },
      { type: 'mrkdwn', text: `*Tier*\n${esc(r.company?.tier || '—')}` },
      { type: 'mrkdwn', text: `*Frustration score*\n${r.frustration_score}/100` },
      { type: 'mrkdwn', text: `*Change*\n${r.is_regression ? '📉 regression ' : ''}${esc(delta)}` },
      { type: 'mrkdwn', text: `*Ticket*\n${esc(p.subject || '—')}` },
      { type: 'mrkdwn', text: `*Priority / stage*\n${esc(p.hs_ticket_priority || '—')} / ${esc(p.hs_pipeline_stage || '—')}` },
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: `*Triggers*\n${r.matched_triggers.slice(0, 8).map((t) => `• ${esc(t)}`).join('\n') || '—'}`.slice(0, 2900) } },
  ];
  if (cfg.includePreview) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*Latest customer message* (redacted)\n>${esc(r.preview)}${cfg.showContactName && r.contact?.name ? `\n— ${esc(r.contact.name)}` : ''}`.slice(0, 2900) } });
  if (url) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open ticket in HubSpot' }, url, style: r.severity_tier === 'critical' ? 'danger' : 'primary' }] });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${r.consecutive_follow_ups > 1 ? `${r.consecutive_follow_ups} unanswered customer messages · ` : ''}${r.cooldownBypass ? `cooldown bypassed: ${esc(r.cooldownBypass)} · ` : ''}message ${esc(r.messageId)} · ${esc(r.messageAt)} · run ${esc(cfg.runId)}`.slice(0, 2900) }] });
  return { ticketId: r.ticketId, tier: r.severity_tier, body: { text: `${r.severity_tier.toUpperCase()} frustration on ticket ${r.ticketId} (${r.company?.name || 'unknown account'}): score ${r.frustration_score}/100`, blocks } };
});
return [{ json: { ...g, alerts, slackAllowed: cfg.sendSlackAlerts && alerts.length > 0 } }];

// ─────────────────────────────────────────────────────────────────────────────
// Collect Slack Results
// Joins Slack responses by index and records sent alerts in workflow static
// data (production executions) for the cooldown.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const alerts = $('Emit Slack Alerts').all();
const resp = $input.all();
if (resp.length !== alerts.length) throw new Error(`Slack result mismatch: ${alerts.length} alerts vs ${resp.length} responses.`);
const results = alerts.map((a, i) => ({ ticketId: a.json.ticketId, tier: a.json.tier, ok: !resp[i].json.error, error: resp[i].json.error ? String(resp[i].json.error.message || resp[i].json.error).slice(0, 200) : null }));
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
if (store && cfg.executionMode === 'production') {
  store.alerts = store.alerts || {};
  for (const r of results.filter((x) => x.ok)) store.alerts[r.ticketId] = { at: Date.now(), tier: r.tier };
  for (const [k, v] of Object.entries(store.alerts)) if (Date.now() - v.at > 7 * 86400000) delete store.alerts[k];
}
return [{ json: { results, sent: results.filter((r) => r.ok).length, failed: results.filter((r) => !r.ok).length } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build HubSpot Ticket Updates
// For every scored ticket: FRUSTRATION_SCORE_PROPERTY (the regression baseline
// for the next reply). For escalations that fired (Slack sent, or Slack not
// enabled): FLAG_PROPERTY = true, LAST_ALERT_PROPERTY / LAST_ALERT_TIER_PROPERTY,
// and with RAISE_PRIORITY=true hs_ticket_priority = HIGH for critical/high
// (never lowered). Batches of ≤ 100.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const s = $input.first().json;
const gate = $('Build Slack Escalation Alerts').first().json;
let slack = null;
try { slack = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { slack = null; }
const sentOk = new Set(slack ? slack.results.filter((r) => r.ok).map((r) => r.ticketId) : []);
const fired = new Set(gate.escalations.filter((e) => (cfg.sendSlackAlerts ? sentOk.has(e.ticketId) : true)).map((e) => e.ticketId));
const PRIO = { LOW: 0, MEDIUM: 1, HIGH: 2, URGENT: 3 };
const now = new Date().toISOString();
const updates = [];
for (const r of gate.results.filter((x) => x.scored)) {
  const props = {};
  if (cfg.scoreProperty) props[cfg.scoreProperty] = String(r.frustration_score);
  if (fired.has(r.ticketId)) {
    if (cfg.flagProperty) props[cfg.flagProperty] = 'true';
    if (cfg.lastAlertProperty) props[cfg.lastAlertProperty] = now;
    if (cfg.lastAlertTierProperty) props[cfg.lastAlertTierProperty] = r.severity_tier;
    const cur = String(r.ticket?.properties?.hs_ticket_priority || '').toUpperCase();
    if (cfg.raisePriority && ['critical', 'high'].includes(r.severity_tier) && (PRIO[cur] ?? -1) < PRIO.HIGH) props.hs_ticket_priority = 'HIGH';
  }
  if (Object.keys(props).length) updates.push({ id: r.ticketId, properties: props });
}
const batches = [];
for (let i = 0; i < updates.length; i += 100) batches.push({ batchNo: batches.length + 1, body: { inputs: updates.slice(i, i + 100) } });
return [{ json: { updates, batches, fired: [...fired], writeAllowed: cfg.writeToHubspot && batches.length > 0 } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Run Summary
// One JSON document for ALERT_WEBHOOK_URL (incident tooling, data warehouse):
// counts, escalated / suppressed ticket IDs, delivery results. No message text.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const g = $('Build Slack Escalation Alerts').first().json;
let sl = null; try { sl = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { sl = null; }
const body = {
  event: 'hubspot.ticket_frustration.run', runId: cfg.runId, generatedAt: new Date().toISOString(),
  mode: cfg.sandboxMode ? 'sandbox' : cfg.sendSlackAlerts ? 'live' : 'dry_run', source: g.source, counts: g.counts,
  escalations: g.escalations.map((e) => ({ ticket_id: e.ticketId, tier: e.severity_tier, score: e.frustration_score, regression: e.is_regression, delta: e.sentiment_delta, company: e.company?.name || null, triggers: e.matched_triggers.map((t) => t.split(':')[0]) })),
  suppressed: g.suppressed, slack: sl ? { sent: sl.sent, failed: sl.failed } : null,
};
const worth = g.escalations.length > 0 || (sl && sl.failed > 0) || cfg.notifyOnEveryRun;
return [{ json: { body, sendAllowed: cfg.webhookEnabled && worth } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path: per-ticket scores, tiers, triggers, skips,
// suppressions, Slack and HubSpot results. Message previews are excluded;
// only IDs, scores and trigger labels are kept. No secrets.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const one = (n) => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const all = (n) => { try { return $(n).isExecuted ? $(n).all().map((i) => i.json) : []; } catch (e) { return []; } };
const wh = one('Parse & Verify Webhook Events');
const res = one('Resolve Thread & Ticket');
const g = one('Build Slack Escalation Alerts');
const sl = one('Collect Slack Results');
const fl = one('Build HubSpot Ticket Updates');
const hu = all('HubSpot: Flag Tickets');
const sum = all('Webhook: Post Run Summary');
const sc = g || one('Sentiment Regression & Frustration Scoring');

let outcome = 'no_tickets';
if (sc) {
  if (!sc.counts.scored) outcome = 'no_customer_messages_to_score';
  else if (!g || !g.escalations.length) outcome = sc.counts.should_escalate ? 'escalations_suppressed' : 'no_escalations';
  else if (cfg.sandboxMode) outcome = 'escalations_found_sandbox';
  else if (!cfg.sendSlackAlerts) outcome = cfg.dryRun ? 'escalations_found_dry_run' : 'escalations_found_slack_disabled';
  else if (sl && sl.failed) outcome = sl.sent ? 'escalated_partially' : 'escalation_failed';
  else outcome = 'escalated';
}
const status = (list) => (!list.length ? 'not_sent' : list.some((x) => x.error) ? 'failed' : 'sent');
return [{ json: {
  workflow: 'n8n-hubspot-support-ticket-frustration-slack-escalation',
  runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, sendSlackAlerts: cfg.sendSlackAlerts, writeToHubspot: cfg.writeToHubspot },
  thresholds: { escalateMinTier: cfg.escalateMinTier, critical: cfg.criticalThreshold, high: cfg.highThreshold, moderate: cfg.moderateThreshold, regressionDelta: cfg.regressionDelta, cooldownHours: cfg.cooldownHours },
  source: sc ? sc.source : (wh ? 'webhook' : null),
  webhook: wh ? { signature: wh.signature, received: wh.received, items: wh.items.length, ignored: wh.ignored } : null,
  dropped: res ? (res.dropped || []) : [],
  counts: sc ? sc.counts : null,
  tickets: sc ? sc.results.map((r) => ({ ticketId: r.ticketId, scored: r.scored, skipReason: r.skipReason || null, score: r.frustration_score ?? null, tier: r.severity_tier || null, delta: r.sentiment_delta ?? null, regression: r.is_regression || false, triggers: r.matched_triggers || [], negated: r.negated_triggers || [], ignoredMessages: r.ignoredMessages.map((m) => m.reason), shouldEscalate: r.should_escalate })) : [],
  escalated: g ? g.escalations.map((e) => e.ticketId) : [],
  suppressed: g ? g.suppressed : [],
  slack: sl ? sl.results : [],
  hubspot: { updatesPrepared: fl ? fl.updates.length : 0, batches: hu.length, status: status(hu), updated: hu.reduce((n, x) => n + (Array.isArray(x.results) ? x.results.length : 0), 0) },
  runSummaryWebhook: status(sum),
} }];
